# rule: block(br,bc) = A flipped vertically if br even, flipped horizontally if bc even
def f(A):
    H,W=A.shape
    o=np.zeros((3*H,2*W),int)
    for br in range(3):
        a=A.copy()
        if br%2==0: a=a[::-1,:]
        for bc in range(2):
            b=a.copy()
            if bc%2==0: b=b[:,::-1]
            o[br*H:(br+1)*H, bc*W:(bc+1)*W]=b
    return o
